#pragma once
#include <juce_audio_basics/juce_audio_basics.h>
#include <cmath>
#include <vector>
#include "Dsp.h"

namespace lp
{

// A sound the engine plays. Every built-in one is generated by the code in this
// file from pure math: no recorded samples, so they belong entirely to this project.
struct SourceSound
{
    juce::String name;
    std::vector<float> data;   // mono
    double sampleRate = 48000.0;
    double rootHz = 261.6256;  // the pitch of the sound
};

enum class SoundId { Glass, Choir, FeltPiano, MusicBox, Nylon, Strings, Vapor, UserSample, Auto };
constexpr int kNumBuiltIns = 7;

namespace sources
{
    constexpr double kRate = 48000.0;
    constexpr double kC4 = 261.6256;
    constexpr double kTwoPi = 6.283185307179586;

    // ratio to the root, amplitude, and seconds to fade away (0 = keeps ringing)
    struct Partial { double ratio; double amp; double decay; };

    inline void normalise (std::vector<float>& d)
    {
        float peak = 0.0f;
        for (auto v : d) peak = std::max (peak, std::abs (v));
        if (peak > 0.0f)
            for (auto& v : d) v *= 0.9f / peak;
    }

    inline SourceSound make (const juce::String& name, double seconds, double root)
    {
        SourceSound s;
        s.name = name;
        s.sampleRate = kRate;
        s.rootHz = root;
        s.data.assign ((size_t) (seconds * kRate), 0.0f);
        return s;
    }

    // Sum of sine partials. Sustained partials slowly "breathe" so grains taken
    // from different places sound a little different.
    inline void addPartials (SourceSound& s, const std::vector<Partial>& partials, double vibrato,
                             double breathe, uint32_t seed)
    {
        juce::Random rng ((juce::int64) seed);
        const int n = (int) s.data.size();
        for (auto& p : partials)
        {
            double phase = rng.nextDouble() * kTwoPi;
            const double lfoRate = 0.07 + rng.nextDouble() * 0.35;
            const double lfoPhase = rng.nextDouble() * kTwoPi;
            const double depth = p.decay > 0 ? 0.0 : breathe * (0.4 + rng.nextDouble() * 0.6);
            const double k = p.decay > 0 ? std::log (0.001) / (p.decay * kRate) : 0.0;
            double env = p.amp;
            const double envMul = std::exp (k);
            for (int i = 0; i < n; ++i)
            {
                const double t = i / kRate;
                phase += kTwoPi * s.rootHz * p.ratio * (1.0 + vibrato * std::sin (kTwoPi * 5.1 * t)) / kRate;
                const double b = 1.0 - depth * (0.5 + 0.5 * std::sin (kTwoPi * lfoRate * t + lfoPhase));
                s.data[(size_t) i] += (float) (env * b * std::sin (phase));
                env *= envMul;
                if (p.decay > 0 && env < 1e-6) break;
            }
        }
    }

    // Detuned sawtooth voices (strings and synths), band-limited.
    inline void addSaws (SourceSound& s, const std::vector<double>& detuneCents, int harmonics,
                         double vibratoRate, double vibratoDepth, uint32_t seed)
    {
        juce::Random rng ((juce::int64) seed);
        const int n = (int) s.data.size();
        for (auto c : detuneCents)
        {
            const double f = s.rootHz * std::pow (2.0, c / 1200.0);
            const int nh = std::min (harmonics, (int) (16000.0 / f));
            double phase = rng.nextDouble() * kTwoPi;
            const double vr = vibratoRate * (0.8 + 0.4 * rng.nextDouble());
            const double vp = rng.nextDouble() * kTwoPi;
            for (int i = 0; i < n; ++i)
            {
                phase += kTwoPi * f * (1.0 + vibratoDepth * std::sin (kTwoPi * vr * i / kRate + vp)) / kRate;
                if (phase > kTwoPi * 1000.0) phase -= kTwoPi * 1000.0;
                double sum = 0;
                for (int h = 1; h <= nh; ++h)
                    sum += std::sin (h * phase) / h;
                s.data[(size_t) i] += (float) (sum * 0.5);
            }
        }
    }

    inline void lowpass (SourceSound& s, float hz, float q)
    {
        dsp::SVF f;
        f.setup (hz, q, (float) kRate);
        for (auto& v : s.data) { f.tick (v); v = f.lp; }
    }

    //==========================================================================

    // Bright glass bells that keep ringing, with soft shimmering overtones.
    inline SourceSound glass()
    {
        auto s = make ("Glass", 4.0, kC4);
        addPartials (s, { { 1.0, 1.0, 0 }, { 2.0, 0.42, 0 }, { 3.0, 0.2, 0 }, { 2.76, 0.18, 0 },
                          { 4.07, 0.14, 0 }, { 5.4, 0.08, 0 }, { 8.02, 0.04, 0 }, { 1.003, 0.5, 0 } },
                     0.0, 0.55, 11);
        normalise (s.data);
        return s;
    }

    // "Aah" voices: harmonics shaped by vowel formants, three singers plus breath.
    inline SourceSound choir()
    {
        auto s = make ("Choir", 4.0, kC4);
        const double formants[3][3] = { { 700, 130, 1.0 }, { 1220, 150, 0.5 }, { 2600, 260, 0.25 } };
        std::vector<Partial> p;
        for (int voice = 0; voice < 3; ++voice)
        {
            const double detune = voice == 0 ? 1.0 : (voice == 1 ? 1.0035 : 0.9967);
            for (int k = 1; k <= 30; ++k)
            {
                const double f = kC4 * k;
                double a = 0.15 / k;
                for (auto& fm : formants)
                    a += fm[2] * std::exp (-0.5 * std::pow ((f - fm[0]) / fm[1], 2.0));
                p.push_back ({ k * detune, a / k * 4.0, 0 });
            }
        }
        addPartials (s, p, 0.005, 0.5, 51);

        // breath through the vowel
        dsp::SVF f1, f2;
        f1.setup (700.0f, 3.0f, (float) kRate);
        f2.setup (1220.0f, 3.0f, (float) kRate);
        dsp::Noise nz;
        float peak = 0;
        for (auto v : s.data) peak = std::max (peak, std::abs (v));
        for (auto& v : s.data)
        {
            const float x = nz.next();
            f1.tick (x);
            f2.tick (x);
            v += (f1.bp + 0.6f * f2.bp) * peak * 0.12f;
        }
        normalise (s.data);
        return s;
    }

    // Soft felt piano: struck, slightly out-of-tune string pairs that fade away.
    inline SourceSound feltPiano()
    {
        auto s = make ("Felt Piano", 5.0, kC4);
        std::vector<Partial> p;
        for (int k = 1; k <= 18; ++k)
        {
            const double ratio = k * std::sqrt (1.0 + 0.0004 * k * k);
            const double amp = std::pow ((double) k, -1.1) * std::exp (-(k - 1) / 5.0);
            const double decay = 5.5 / (1.0 + 0.45 * (k - 1));
            p.push_back ({ ratio, amp, decay });
            p.push_back ({ ratio * 1.0006, amp * 0.6, decay * 0.9 }); // second string
        }
        addPartials (s, p, 0.0, 0.0, 37);

        // felt hammer thump
        dsp::SVF lp;
        lp.setup (900.0f, 0.7f, (float) kRate);
        dsp::Noise nz;
        const int thump = (int) (0.025 * kRate);
        for (int i = 0; i < thump; ++i)
        {
            lp.tick (nz.next());
            s.data[(size_t) i] += lp.lp * 0.5f * (1.0f - (float) i / thump);
        }
        // a gentle start instead of a click
        for (int i = 0; i < 96; ++i) s.data[(size_t) i] *= (float) i / 96.0f;
        normalise (s.data);
        return s;
    }

    // Tiny metal tines being plucked, like a wind-up music box.
    inline SourceSound musicBox()
    {
        auto s = make ("Music Box", 3.0, 523.2511);
        addPartials (s, { { 1.0, 1.0, 2.8 }, { 2.0, 0.22, 1.3 }, { 3.0, 0.08, 0.6 }, { 5.4, 0.3, 0.4 },
                          { 8.93, 0.16, 0.2 }, { 13.3, 0.07, 0.1 } },
                     0.0, 0.0, 23);
        dsp::Noise nz;
        dsp::SVF hp;
        hp.setup (4000.0f, 0.7f, (float) kRate);
        for (int i = 0; i < (int) (0.004 * kRate); ++i)
        {
            hp.tick (nz.next());
            s.data[(size_t) i] += hp.hp * 0.6f;
        }
        normalise (s.data);
        return s;
    }

    // Nylon guitar string (a plucked-string model).
    inline SourceSound nylon()
    {
        auto s = make ("Nylon Guitar", 4.0, kC4);
        const int period = (int) std::round (kRate / kC4 - 0.5);
        s.rootHz = kRate / (period + 0.5);
        std::vector<float> line ((size_t) period);
        dsp::Noise nz;
        dsp::SVF soft;
        soft.setup (2500.0f, 0.6f, (float) kRate); // soft fingertip, not a pick
        for (int i = 0; i < period * 4; ++i) { soft.tick (nz.next()); line[(size_t) (i % period)] = soft.lp; }
        // pluck a little away from the bridge
        const int pluckPos = period / 5;
        std::vector<float> plucked = line;
        for (int i = 0; i < period; ++i)
            plucked[(size_t) i] = line[(size_t) i] - line[(size_t) ((i + pluckPos) % period)];
        line = plucked;

        dsp::SVF body1, body2;
        body1.setup (110.0f, 2.0f, (float) kRate);
        body2.setup (230.0f, 2.5f, (float) kRate);
        int idx = 0;
        for (auto& out : s.data)
        {
            const int next = (idx + 1) % period;
            const float y = line[(size_t) idx];
            line[(size_t) idx] = 0.9965f * 0.5f * (y + line[(size_t) next]);
            idx = next;
            body1.tick (y);
            body2.tick (y);
            out = y + body1.bp * 0.35f + body2.bp * 0.25f;
        }
        normalise (s.data);
        return s;
    }

    // An old string section on tape: warm, slow, a little wobbly.
    inline SourceSound strings()
    {
        auto s = make ("Tape Strings", 3.0, kC4);
        addSaws (s, { -11.0, -5.0, 0.0, 6.0, 12.0 }, 40, 4.6, 0.0022, 61);
        lowpass (s, 2600.0f, 0.6f);
        lowpass (s, 4200.0f, 0.6f);
        normalise (s.data);
        return s;
    }

    // A wide, glossy supersaw synth with a sub underneath.
    inline SourceSound vapor()
    {
        auto s = make ("Vapor Synth", 3.0, kC4);
        addSaws (s, { -26.0, -15.0, -6.0, 0.0, 7.0, 16.0, 27.0 }, 48, 0.3, 0.0008, 71);
        addPartials (s, { { 0.5, 1.6, 0 } }, 0.0, 0.0, 72);
        lowpass (s, 7000.0f, 0.8f);
        normalise (s.data);
        return s;
    }

    // Built once and shared by every copy of the plugin.
    inline const std::vector<SourceSound>& library()
    {
        static const std::vector<SourceSound> lib = []
        {
            std::vector<SourceSound> v;
            v.push_back (glass());
            v.push_back (choir());
            v.push_back (feltPiano());
            v.push_back (musicBox());
            v.push_back (nylon());
            v.push_back (strings());
            v.push_back (vapor());
            return v;
        }();
        return lib;
    }
} // namespace sources

} // namespace lp
